	default:
		candidates = []string{filepath.Join(usr.HomeDir, ".local", "share", "zed", "threads", "threads.db")}
	}
	for _, path := range candidates {
		if _, err := os.Stat(path); err == nil {
			return path, nil
		}
	}
	return "", fmt.Errorf("not found")
}

func main() {
	dbPath, _ := getZedDBPath()
	db, _ := sql.Open("sqlite3", dbPath+"?mode=ro")
	defer db.Close()

	var id, summary, updatedAt, dataType string
	var data []byte
	db.QueryRow(`SELECT id, summary, updated_at, data_type, data FROM threads ORDER BY updated_at DESC LIMIT 1`).Scan(&id, &summary, &updatedAt, &dataType, &data)

	var rawData []byte
	if dataType == "zstd" {
		decoder, _ := zstd.NewReader(bytes.NewReader(data))
		rawData, _ = io.ReadAll(decoder)
		decoder.Close()
	} else {
		rawData = data
	}

	var parsed map[string]interface{}
	json.Unmarshal(rawData, &parsed)

	// Top-level fields
	fmt.Printf("\n=== Top-level fields ===\n")
	fmt.Printf("version: %v\n", parsed["version"])
	fmt.Printf("title: %v\n", parsed["title"])
	fmt.Printf("model: %v\n", parsed["model"])
	fmt.Printf("subagent_context: %v\n", parsed["subagent_context"])
	fmt.Printf("thinking_effort: %v\n", parsed["thinking_effort"])
	fmt.Printf("detailed_summary: %v\n", parsed["detailed_summary"])
	fmt.Printf("profile: %v\n", parsed["profile"])
	fmt.Printf("speed: %v\n", parsed["speed"])
	fmt.Printf("thinking_enabled: %v\n", parsed["thinking_enabled"])
	fmt.Printf("imported: %v\n", parsed["imported"])

	// Examine messages
	if msgs, ok := parsed["messages"].([]interface{}); ok {
		fmt.Printf("\n=== Messages (total: %d) ===\n", len(msgs))

		// Look at a few messages
		for i := 0; i < min(3, len(msgs)); i++ {
			msg := msgs[i].(map[string]interface{})
			fmt.Printf("\n--- Message %d ---\n", i)

			if user, ok := msg["User"].(map[string]interface{}); ok {
				fmt.Printf("  Type: User\n")
				if content, ok := user["content"].([]interface{}); ok {
					fmt.Printf("  Content items: %d\n", len(content))
					for j, c := range content {
						if j > 2 {
							break
						}
						cm := c.(map[string]interface{})
						fmt.Printf("    [%d] keys: %v\n", j, getKeys(cm))
					}
				}
			}
			if agent, ok := msg["Agent"].(map[string]interface{}); ok {
				fmt.Printf("  Type: Agent\n")
				if content, ok := agent["content"].([]interface{}); ok {
					fmt.Printf("  Content items: %d\n", len(content))
					for j, c := range content {
						if j > 2 {
							break
						}
						cm := c.(map[string]interface{})
						fmt.Printf("    [%d] keys: %v\n", j, getKeys(cm))
						// Check for text content
						if text, ok := cm["Text"].(string); ok {
							fmt.Printf("        Text preview: %.50s...\n", text)
						}
						if toolUse, ok := cm["ToolUse"].(map[string]interface{}); ok {
							fmt.Printf("        ToolUse: %v\n", toolUse["name"])
						}
						if toolResult, ok := cm["ToolResult"].(map[string]interface{}); ok {
							fmt.Printf("        ToolResult keys: %v\n", getKeys(toolResult))
						}
					}
				}
			}
		}
	}

	// Token usage sample
	if tokens, ok := parsed["request_token_usage"].(map[string]interface{}); ok {
		fmt.Printf("\n=== Token Usage Sample ===\n")
		var firstKey string
		for k := range tokens {
			firstKey = k
			break
		}
		if firstKey != "" {
			if req, ok := tokens[firstKey].(map[string]interface{}); ok {
				fmt.Printf("First request keys: %v\n", getKeys(req))
				fmt.Printf("input_tokens: %v\n", req["input_tokens"])
				fmt.Printf("output_tokens: %v\n", req["output_tokens"])
			}
		}
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func getKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	return keys
}

