 func main() {
 	if len(os.Args) < 2 {
 		printHelp()
 		os.Exit(1)
 	}

 	subcommand := os.Args[1]

 	switch subcommand {
 	case "help", "--help", "-h":
 		printHelp()
 	case "info":
 		handleInfo()
 	case "transcript":
 		handleTranscript()
 	case "start":
 		handleStart()
 	case "stop":
 		handleStop()
 	case "parse-hook":
 		handleParseHook()
 	case "get-session-dir":
 		handleGetSessionDir()
 	case "resolve-session-file":
 		handleResolveSessionFile()
 	case "install-hooks":
 		handleInstallHooks()
 	case "uninstall-hooks":
 		handleUninstallHooks()
 	case "are-hooks-installed":
 		handleAreHooksInstalled()
 	case "calculate-tokens":
 		handleCalculateTokens()
 	case "attach":
 		handleAttach()
 	case "extract-branch":
 		handleExtractBranch()
 	case "end-session":
 		handleEndSession()
 	default:
 		// Required by the Entire External Agent Protocol: Exit gracefully if unsupported
 		fmt.Println("{}")
 		os.Exit(0)
 	}
 }

